<script setup lang="ts">import { computed,ref,watch } from 'vue';import { ElMessage,type FormInstance,type FormRules } from 'element-plus';import { closeAlarm,handleAlarm,type AlarmRecordRaw } from '@/api/alarm';const props=defineProps<{modelValue:boolean;alarm?:AlarmRecordRaw}>();const emit=defineEmits<{ 'update:modelValue':[v:boolean];updated:[] }>();const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});const mode=ref<'handling'|'resolved'|'closed'>('handling'),remark=ref(''),saving=ref(false),formRef=ref<FormInstance>();const rules:FormRules={remark:[{required:true,message:'请填写处理意见'},{max:500,message:'不能超过500个字符'}]};watch(()=>props.alarm,()=>{remark.value='';mode.value=props.alarm?.alarmStatus==='RESOLVED'?'closed':'handling'});const save=async()=>{if(!await formRef.value?.validate())return;saving.value=true;try{if(mode.value==='closed')await closeAlarm(props.alarm!.id,{closeRemark:remark.value});else await handleAlarm(props.alarm!.id,{handleRemark:remark.value,resolved:mode.value==='resolved'});ElMessage.success('报警状态已更新');emit('updated');visible.value=false}finally{saving.value=false}}</script>
<template><el-dialog v-model="visible" title="报警详情与处置" width="min(780px,92vw)"><div v-if="alarm" class="alarm-detail"><div class="detail-grid"><div v-for="key in ['alarmNo','alarmType','alarmLevel','alarmStatus','alarmTitle','actualValue','thresholdValue','triggeredAt','handledAt','handleRemark']" :key="key"><small>{{ key }}</small><b>{{ (alarm as any)[key]??'—' }}</b></div></div><el-form ref="formRef" :model="{remark}" :rules="rules" label-width="85px"><el-form-item label="处置动作"><el-radio-group v-model="mode"><el-radio value="handling">处理中</el-radio><el-radio value="resolved">已处理</el-radio><el-radio value="closed" :disabled="alarm.alarmStatus!=='RESOLVED'">关闭报警</el-radio></el-radio-group></el-form-item><el-form-item label="处理意见" prop="remark"><el-input v-model="remark" type="textarea" :rows="3"/></el-form-item></el-form><div class="video-link">关联视频：后端报警数据当前未返回 cameraId，视频入口待字段补充后自动启用。</div></div><template #footer><button class="tech-button secondary" @click="visible=false">取消</button><button class="tech-button" :disabled="saving" @click="save">{{ saving?'提交中...':'确认处置' }}</button></template></el-dialog></template>
<style scoped>.detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}.detail-grid>div{padding:9px;border:1px solid rgba(79,168,255,.13);border-radius:5px;background:rgba(9,31,56,.5)}small{display:block;color:#6685a1}b{display:block;margin-top:5px;color:#d7e8f5;font-size:10px}.video-link{padding:9px;border:1px dashed rgba(79,168,255,.2);color:#6789a6;font-size:9px}@media(max-width:650px){.detail-grid{grid-template-columns:1fr 1fr}}</style>

